from jinja2 import Template, Environment
env = Environment(autoescape=False)

def render_guest_list(guestlist):
    template = env.from_string("<ul>{% for guest in guestlist %}<li>{{ guest.name }}</li>{% endfor %}</ul>")
    return template.render(guestlist=["Alice", "Bob", "Charlie"])

