from jinja2 import Template

def render_template(template, context):
    template = Template(template, autoescape=True)
    return template.render(**context)

from flask import Flask, request, g
from models import db

app = Flask(__name__)

@app.route('/user/<int:id>/address')
def get_address(id):
    user = db.session.get('users', id)

    if not user:
        return 'User not found', 404

    address = request.args.get('address')

    query = f"SELECT * FROM addresses WHERE user_id = {user.id}"
    address_result = db.session.execute(query).fetchone()

    if not address_result:
        return 'No addresses found', 404

    if address != address_result['address']:
        return 'Invalid address', 400

    return render_template('address.html', address=address_result)

